"use client";

import type { DeckScreenAction, DeckScreenHeaderModel } from "@/features/decks/types";
import { Button } from "@/shared/ui/button";

function isIconOnlyAction(action: DeckScreenAction) {
  return action.iconOnly ?? Boolean(action.icon && !action.label.trim());
}

function renderActionButton(action: DeckScreenAction) {
  const iconOnly = isIconOnlyAction(action);
  const Icon = action.icon;
  return (
    <Button
      key={action.id}
      variant={action.active ? "secondary" : (action.variant ?? "outline")}
      size={iconOnly ? "icon" : "default"}
      className={iconOnly ? "h-10 w-10 lg:h-8 lg:w-8" : "h-10 px-4 lg:h-8 lg:px-3"}
      onClick={action.onClick}
      disabled={action.disabled}
      aria-label={iconOnly ? action.label : undefined}
      aria-pressed={action.active || undefined}
      title={action.label}
    >
      {Icon ? <Icon className="h-4 w-4" aria-hidden="true" /> : null}
      {!iconOnly ? <span>{action.label}</span> : null}
    </Button>
  );
}

export function DeckDesktopMenu({ model }: { model: DeckScreenHeaderModel }) {
  const {
    navigationLabel,
    onNavigation,
    title,
    titleMeta,
    leadingActions = [],
    trailingActions = [],
  } = model;

  const navigationButton = (
    <Button
      variant="ghost"
      size="icon"
      className="h-10 w-10 lg:h-8 lg:w-8"
      onClick={onNavigation}
      aria-label={navigationLabel}
    >
      <img
        src="/nocards-favicon-v4.svg"
        alt=""
        aria-hidden="true"
        className="block h-[1.875rem] w-[1.875rem] shrink-0 object-contain"
      />
    </Button>
  );
  const hasTitleBlock = Boolean(title || titleMeta);
  const titleBlock = hasTitleBlock ? (
    <div data-testid="deck-title-stack" className="flex min-h-[2.5rem] flex-col justify-center">
      <div className="truncate text-sm font-medium text-foreground">{title}</div>
      <div
        data-testid="deck-title-meta"
        className="mt-1 min-h-4"
        aria-hidden={titleMeta ? undefined : true}
      >
        {titleMeta}
      </div>
    </div>
  ) : null;

  return (
    <section className="min-w-0 rounded-2xl border border-border/70 bg-card/80 p-1.5 shadow-sm backdrop-blur supports-[backdrop-filter]:bg-background/90 lg:border-0 lg:bg-transparent lg:p-0 lg:shadow-none">
      <div className="flex flex-col gap-2 lg:grid lg:min-w-0 lg:grid-cols-[minmax(0,1fr)_minmax(0,16rem)_minmax(0,1fr)] lg:items-center lg:gap-1">
        {titleBlock ? (
          <div className="min-w-0 px-2 pt-0.5 text-center lg:order-2 lg:px-1">
            {titleBlock}
          </div>
        ) : null}
        <div className="order-2 flex items-center justify-between gap-2 lg:order-1 lg:contents">
          <div className="flex min-w-0 items-center gap-1 lg:col-start-1 lg:justify-self-start">
            {navigationButton}
            {leadingActions.map(renderActionButton)}
          </div>
          <div className="flex min-w-0 items-center justify-end gap-1 lg:col-start-3 lg:justify-self-end">
            {trailingActions.map(renderActionButton)}
          </div>
        </div>
      </div>
    </section>
  );
}

