"use client";

import { DeckDesktopMenu } from "@/features/decks/components/DeckDesktopMenu";
import type { DeckScreenModel } from "@/features/decks/types";
import { cn } from "@/lib/utils";

export function DeckDesktopShell({ model }: { model: DeckScreenModel }) {
  const cardsPane = model.cardsPane;
  const cardsPaneEmptyDesktopContent = cardsPane?.emptyDesktopContent ?? null;
  const cardsPaneContent = cardsPane?.content ?? null;
  const cardsPaneOnDragOver = cardsPane?.onDragOver;
  const cardsPaneOnDragLeave = cardsPane?.onDragLeave;
  const cardsPaneOnDrop = cardsPane?.onDrop;
  const cardsPaneOnScroll = cardsPane?.onScroll;
  const cardsPaneScrollRegionRef = cardsPane?.scrollRegionRef;

  return (
    <div className="desktop-capable-grid grid h-full min-h-0 min-w-0 gap-4 overflow-hidden bg-transparent">
      <main
        className={cn(
          "grid min-h-0 min-w-0 overflow-hidden bg-transparent",
          model.mode === "decks" ? "grid-rows-[1fr]" : "lg:grid-rows-[auto_1fr]",
        )}
      >
        {model.decksContent ? (
          <div className="flex min-h-0 flex-col gap-2.5 pt-2.5 sm:gap-3 sm:pt-3">
            {model.desktopHeader ? (
              <div className="mx-auto w-full max-w-6xl px-2.5 sm:px-4">
                <DeckDesktopMenu model={model.desktopHeader} />
              </div>
            ) : null}
            <div className="mx-auto w-full max-w-6xl px-2.5 sm:px-4">
              {model.decksContent}
            </div>
          </div>
        ) : model.desktopHeader ? (
          <div className="pt-3">
            <div className="mx-auto w-full max-w-6xl px-2.5 sm:px-4">
              <DeckDesktopMenu model={model.desktopHeader} />
            </div>
          </div>
        ) : null}

        {cardsPane ? (
          <div
            ref={cardsPaneScrollRegionRef}
            data-testid="cards-scroll-region"
            className="relative min-h-0 overflow-y-auto overflow-x-hidden px-2.5 py-2.5 pb-[calc(96px+env(safe-area-inset-bottom))] sm:px-4 sm:py-4 lg:px-5 lg:pb-6"
            onDragOver={cardsPaneOnDragOver}
            onDragLeave={cardsPaneOnDragLeave}
            onDrop={cardsPaneOnDrop}
            onScroll={cardsPaneOnScroll}
          >
            {model.desktopViewport && cardsPaneEmptyDesktopContent
              ? cardsPaneEmptyDesktopContent
              : cardsPaneContent}
          </div>
        ) : null}
      </main>
    </div>
  );
}

"use client";

import {
  type LucideIcon,
} from "lucide-react";
import type { DeckScreenDockModel } from "@/features/decks/types";
import { cn } from "@/lib/utils";

function formatCompactBadge(count: number) {
  if (count <= 0) return null;
  return count > 99 ? "99+" : String(count);
}

function formatActionBadge(value: string | null | undefined) {
  if (!value) return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? formatCompactBadge(parsed) ?? value : value;
}

function DeckActionButton({
  icon: Icon,
  label,
  active = false,
  disabled = false,
  badge = null,
  prominent = false,
  desktopSquare = false,
  onClick,
}: {
  icon?: LucideIcon;
  label: string;
  active?: boolean;
  disabled?: boolean;
  badge?: string | null;
  prominent?: boolean;
  desktopSquare?: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      className={cn(
        "pointer-events-auto relative inline-flex h-12 w-full items-center justify-center rounded-2xl border px-3 shadow-sm outline-none transition-[background-color,border-color,color,box-shadow,transform] focus-visible:ring-[3px] focus-visible:ring-ring/40 disabled:pointer-events-none disabled:opacity-50",
        "lg:h-10 lg:rounded-md",
        desktopSquare ? "lg:w-10 lg:px-0" : "lg:w-auto lg:px-4",
        prominent
          ? "border-primary bg-primary text-primary-foreground hover:bg-primary/92"
          : active
            ? "border-border bg-secondary text-secondary-foreground"
            : "border-border bg-card text-muted-foreground hover:bg-accent hover:text-foreground",
      )}
      onClick={onClick}
      disabled={disabled}
      aria-label={label}
      aria-pressed={active || undefined}
      title={label}
    >
      {Icon ? (
        <Icon className="h-5 w-5" aria-hidden="true" />
      ) : (
        <span className="text-sm font-semibold leading-none">
          {label}
        </span>
      )}
      {badge ? (
        <span
          className={cn(
            "pointer-events-none absolute -right-1.5 -top-1.5 inline-flex min-w-5 items-center justify-center rounded-full px-1.5 py-0.5 text-[10px] font-semibold leading-none shadow-sm",
            prominent
              ? "bg-primary-foreground text-primary"
              : "bg-foreground text-background",
          )}
          aria-hidden="true"
        >
          {badge}
        </span>
      ) : null}
    </button>
  );
}

export function DeckMobileActionDock({
  model,
}: {
  model: DeckScreenDockModel;
}) {
  return (
    <div className="pointer-events-none fixed inset-x-0 bottom-0 z-[80] px-3 pb-[calc(12px+env(safe-area-inset-bottom))] pt-3 lg:hidden">
      <div className="pointer-events-auto mx-auto max-w-[min(96vw,34rem)] rounded-[1.4rem] border border-border bg-background/95 p-2 shadow-lg backdrop-blur supports-[backdrop-filter]:bg-background/90 lg:max-w-fit">
        <div
          className={cn(
            "grid gap-2",
            model.actions.length >= 6 ? "grid-cols-6" : "grid-cols-3",
          )}
          aria-label={model.ariaLabel ?? "Cards actions"}
        >
          {model.actions.map((action) => (
            <DeckActionButton
              key={action.id}
              icon={action.icon}
              label={action.label}
              active={action.active}
              disabled={action.disabled}
              badge={formatActionBadge(action.badge)}
              prominent={action.variant === "default"}
              desktopSquare={action.iconOnly ?? Boolean(action.icon)}
              onClick={action.onClick}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

