export function DeckBrowserTable({
  rows,
  selectedDeckKey,
  onSelectDeck,
  onAddSubdeck,
  onRenameTag,
  onResetDeck,
  canResetDeck,
  onDeleteTag,
}: {
  rows: readonly DeckBrowserRow[];
  selectedDeckKey: string;
  onSelectDeck: (tagIds: string[]) => void;
  onAddSubdeck: (tag: Tag) => void;
  onRenameTag: (tag: Tag) => void;
  onResetDeck: (row: DeckBrowserRow) => void;
  canResetDeck?: (row: DeckBrowserRow) => boolean;
  onDeleteTag: (tag: Tag) => void | Promise<void>;
}) {
  const [expandedById, setExpandedById] = React.useState<Record<string, boolean>>({});
  const [menuState, setMenuState] = React.useState<{
    rowId: string;
    top: number;
    left: number;
  } | null>(null);
  const menuRowId = menuState?.rowId ?? null;

  React.useEffect(() => {
    setExpandedById((previous) => {
      let changed = false;
      const next = { ...previous };
      for (const row of rows) {
        if (!row.hasChildren || next[row.id] !== undefined) continue;
        next[row.id] = true;
        changed = true;
      }
      return changed ? next : previous;
    });
  }, [rows]);

  React.useEffect(() => {
    if (!menuState) return;

    const onPointerDown = (event: MouseEvent) => {
      if (event.target instanceof Element && event.target.closest("[data-deck-action-root]")) {
        return;
      }
      setMenuState(null);
    };

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setMenuState(null);
    };

    const onScroll = () => {
      setMenuState(null);
    };

    document.addEventListener("mousedown", onPointerDown);
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("scroll", onScroll, true);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("scroll", onScroll, true);
    };
  }, [menuState]);

  const visibleRows = React.useMemo(
    () =>
      rows.filter((row) => row.ancestorIds.every((ancestorId) => expandedById[ancestorId] !== false)),
    [expandedById, rows],
  );

  return (
    <section className="flex h-auto min-h-0 min-w-0 max-h-[min(60svh,32rem)] flex-col overflow-hidden rounded-[1.25rem] border border-border/70 bg-card/80 shadow-[0_16px_42px_rgb(15_23_42_/_0.08)] sm:max-h-[min(68svh,34rem)] sm:rounded-2xl lg:h-auto lg:max-h-[min(52svh,38rem)]">
      <div className="sticky top-0 z-10 hidden grid-cols-[minmax(0,1fr)_4rem_4rem_4rem_7.5rem_7.5rem_2.25rem] items-center gap-1.5 border-b border-border/70 bg-card/95 px-4 py-3 text-xs font-semibold uppercase tracking-[0.16em] text-muted-foreground backdrop-blur supports-[backdrop-filter]:bg-card/85 lg:grid">
        <div className="px-2 text-left text-sm font-semibold normal-case tracking-normal text-foreground">
          Decks
        </div>
        <div className="pr-1 text-right text-foreground">New</div>
        <div className="pr-1 text-right text-foreground">Learn</div>
        <div className="pr-1 text-right text-foreground">Due</div>
        <div className="pr-1 text-right text-foreground">Time</div>
