import { DeckDesktopShell } from "@/features/decks/components/DeckDesktopShell";
import { DeckMobileShell } from "@/features/decks/components/DeckMobileShell";
import type { DeckScreenModel } from "@/features/decks/types";
import { Modal } from "@/shared/ui/modal";

export function DeckScreen({ model }: { model: DeckScreenModel }) {
  return (
    <>
      <DeckDesktopShell model={model} />
      <DeckMobileShell model={model} />
      <Modal
        open={model.tagPanel.open}
        onClose={model.tagPanel.onClose}
        title={model.tagPanel.title}
        description={model.tagPanel.description}
      >
        {model.tagPanel.content}
      </Modal>
    </>
  );
}

import * as React from "react";
import type {
  DeckScreenCardsPaneModel,
  DeckScreenDockModel,
  DeckScreenHeaderModel,
  DeckScreenModel,
} from "@/features/decks/types";

type UseDeckScreenModelArgs = {
  mode: "decks" | "cards";
  desktopViewport: boolean;
  decksHeader: DeckScreenHeaderModel;
  cardsHeader: DeckScreenHeaderModel;
  decksContent: React.ReactNode;
  cardsPane: DeckScreenCardsPaneModel | null;
  mobileDock: DeckScreenDockModel | null;
  tagPanel: DeckScreenModel["tagPanel"];
};

export function useDeckScreenModel({
  mode,
  desktopViewport,
  decksHeader,
  cardsHeader,
  decksContent,
  cardsPane,
  mobileDock,
  tagPanel,
}: UseDeckScreenModelArgs): DeckScreenModel {
  return React.useMemo(
    () => ({
      mode,
      desktopViewport,
      desktopHeader:
        mode === "decks"
          ? decksHeader
          : desktopViewport
            ? cardsHeader
            : null,
      decksContent: mode === "decks" ? decksContent : null,
      cardsPane: mode === "cards" ? cardsPane : null,
      mobileDock,
      tagPanel,
    }),
    [
      cardsHeader,
      cardsPane,
      decksContent,
      decksHeader,
      desktopViewport,
      mobileDock,
      mode,
      tagPanel,
    ],
  );
}

